function BetterUI.hud_layout.skill_open_plate_rect()
  local vis_l = HL_SO_CONTENT_L - BetterUI.hud_layout.SKILL_OPEN_PAD
  local vis_w = HL_SO_CONTENT_R - HL_SO_CONTENT_L + 2 * BetterUI.hud_layout.SKILL_OPEN_PAD
  local vis_h = BetterUI.hud_layout.SKILL_OPEN_H
  local w = vis_w / (HL_PLATE_VX1 - HL_PLATE_VX0)
  local h = vis_h / (HL_PLATE_VY1 - HL_PLATE_VY0)
  return vis_l - w * HL_PLATE_VX0, vis_h / 2 + h * HL_PLATE_VY0, w, h
end

function BetterUI.hud_layout.slot_plate_rect()
  local g = BetterUI.hud_layout.AURA_SLOT_PLATE_GROW or 1
  local w, h = HL_SLOT_MESH_W * g, HL_SLOT_MESH_H * g
  return HL_SLOT_MESH_X + (HL_SLOT_MESH_W - w) / 2, HL_SLOT_MESH_Y + (h - HL_SLOT_MESH_H) / 2, w, h
end

function BetterUI.hud_layout.release_plate_rect()
  local s = BetterUI.hud_layout.AURA_RELEASE_SCALE
  local _, _, _, sh = BetterUI.hud_layout.slot_plate_rect()
  local vis_h = sh * (HL_PLATE_VY1 - HL_PLATE_VY0) * BetterUI.hud_layout.AURA_SLOT_SCALE / s
  local vis_l = HL_REL_CONTENT_L - BetterUI.hud_layout.AURA_RELEASE_PAD
  local vis_w = HL_REL_CONTENT_R - HL_REL_CONTENT_L + 2 * BetterUI.hud_layout.AURA_RELEASE_PAD
  local w = vis_w / (HL_PLATE_VX1 - HL_PLATE_VX0)
  local h = vis_h / (HL_PLATE_VY1 - HL_PLATE_VY0)
  return vis_l - w * HL_PLATE_VX0, vis_h / 2 + h * HL_PLATE_VY0, w, h
end

local function HL_ReleaseAtc()
  local ok1, gx, gy = pcall(funcLuaMenuCommand, HL_CMND_GPOS, HL_BASE, 0, HL_NODE_GAIJI)
  local ok2, ax, ay = pcall(funcLuaMenuCommand, HL_CMND_GPOS, HL_BASE, 0, HL_NODE_ATC04)
  local ok3, cx = pcall(funcLuaMenuCommand, HL_CMND_GPOS, HL_BASE, 0, HL_NODE_CMD0101)
  local ok4, _, uy = pcall(funcLuaMenuCommand, HL_CMND_GPOS, HL_BASE, 0, HL_NODE_CMD0104)
  if not (ok1 and ok2 and ok3 and ok4) or type(gx) ~= "number" or type(gy) ~= "number" or type(ax) ~= "number"
    or type(ay) ~= "number" or type(cx) ~= "number" or type(uy) ~= "number" then
    return HL_REL_ATC_DX, HL_REL_ATC_DY
  end
  local kx, ky = (cx - gx) / 128, (uy - gy) / 76
  if kx < 0.25 or kx > 4 or math.abs(ky) < 0.25 or math.abs(ky) > 4 then
    return HL_REL_ATC_DX, HL_REL_ATC_DY
  end
  local dx, dy = (ax - gx) / kx, (ay - gy) / ky
  if math.abs(dx) > 1920 or math.abs(dy) > 1080 then
    return HL_REL_ATC_DX, HL_REL_ATC_DY
  end
  return dx, dy
end

local function HL_TacticsMode()
  if type(funcLuaCommand) ~= "function" then
    return false
  end
  local ok, on = pcall(funcLuaCommand, HL_CMND_TACTICS_MODE)
  return ok and on == true
end

-- Measures the menu offset every frame (the tactics page slides the cross), relative to the layer root so the current offset is included.
local function HL_MenuDx()
  if not BetterUI.hud_layout.TACTICS_MENU_LEFT or type(funcLuaCommand) ~= "function" then
    return 0
  end
  local on = HL_TacticsMode()
  if not on and hl_menu_dx ~= 0 and type(IsPlayCommandSelectAnime) == "function" then
    local ok2, busy = pcall(IsPlayCommandSelectAnime)
    on = ok2 and busy == true
  end
  if not on then
    return 0
  end
  local ok3, gx = pcall(funcLuaMenuCommand, HL_CMND_GPOS, HL_BASE, 0, HL_NODE_GAIJI)
  local ok4, ox = pcall(funcLuaMenuCommand, HL_CMND_GPOS, HL_BASE, 0, HL_NODE_OUT)
  local ok5, cx = pcall(funcLuaMenuCommand, HL_CMND_GPOS, HL_BASE, 0, HL_NODE_CMD0101)
  if not ok3 or not ok4 or type(gx) ~= "number" or type(ox) ~= "number" then
    return hl_menu_dx
  end
  -- Computes the global units per layout unit.
  local k = 1
  if ok5 and type(cx) == "number" and (cx - gx) / 128 > 0.25 and (cx - gx) / 128 < 4 then
    k = (cx - gx) / 128
  end
  local rel = (gx - ox) / k
  if rel >= 0 or rel <= -BetterUI.hud_layout.SCREEN_W then
    return hl_menu_dx
  end
  return -BetterUI.hud_layout.SCREEN_W + BetterUI.hud_layout.TACTICS_MENU_CROSS_X - rel
end

local function HL_Place(layer)
  if layer == HL_GOAHEAD then
    local s = BetterUI.hud_layout.GOAHEAD_SCALE
    VRFW.host.menu_command(HL_CMND_SCALE, HL_GOAHEAD, s, s, 1, 0)
    VRFW.host.menu_command(HL_CMND_POS, HL_GOAHEAD, BetterUI.hud_layout.GOAHEAD_X - HL_GOAHEAD_ATC_X, BetterUI.hud_layout.GOAHEAD_Y - HL_GOAHEAD_ATC_Y, 0, 0)
  elseif layer == HL_AURA_REL then
    local s = BetterUI.hud_layout.AURA_RELEASE_SCALE
    VRFW.host.menu_command(HL_CMND_SCALE, HL_AURA_REL, s, s, 1, 0)
    if BetterUI.hud_layout.AURA_RELEASE_SQUARE then
      local x, y, w, h = BetterUI.hud_layout.release_plate_rect()
      VRFW.host.menu_command(HL_CMND_NODE_POS, HL_AURA_REL, 0, HL_REL_MESH, 0, x)
      VRFW.host.menu_command(HL_CMND_NODE_POS, HL_AURA_REL, 0, HL_REL_MESH, 1, y)
      VRFW.host.menu_command(HL_CMND_NODE_SIZE, HL_AURA_REL, 0, HL_REL_MESH, w, h)
      local ax = HL_ReleaseAtc()
      local vis_l = x + w * HL_PLATE_VX0
      VRFW.host.menu_command(HL_CMND_POS, HL_AURA_REL, BetterUI.hud_layout.AURA_RELEASE_LEFT - ax - s * vis_l, BetterUI.hud_layout.AURA_RELEASE_DY, 0, 0)
    end
  elseif layer == HL_AURA_SLOT then
    local s = BetterUI.hud_layout.AURA_SLOT_SCALE
    VRFW.host.menu_command(HL_CMND_SCALE, HL_AURA_SLOT, s, s, 1, 0)
    VRFW.host.menu_command(HL_CMND_POS, HL_AURA_SLOT, BetterUI.hud_layout.AURA_SLOT_RIGHT - s * HL_SLOT_RIGHT, HL_SLOT_CY * (1 - s), 0, 0)
    local x, y, w, h = BetterUI.hud_layout.slot_plate_rect()
    VRFW.host.menu_command(HL_CMND_NODE_POS, HL_AURA_SLOT, 0, HL_SLOT_MESH, 0, x)
    VRFW.host.menu_command(HL_CMND_NODE_POS, HL_AURA_SLOT, 0, HL_SLOT_MESH, 1, y)
    VRFW.host.menu_command(HL_CMND_NODE_SIZE, HL_AURA_SLOT, 0, HL_SLOT_MESH, w, h)
  elseif layer == HL_SKILL_OPEN then
    local s = BetterUI.hud_layout.SKILL_OPEN_SCALE
    local x, y, w, h = BetterUI.hud_layout.skill_open_plate_rect()
    VRFW.host.menu_command(HL_CMND_NODE_POS, HL_SKILL_OPEN, 0, HL_SO_MESH, 0, x)
    VRFW.host.menu_command(HL_CMND_NODE_POS, HL_SKILL_OPEN, 0, HL_SO_MESH, 1, y)
    VRFW.host.menu_command(HL_CMND_NODE_SIZE, HL_SKILL_OPEN, 0, HL_SO_MESH, w, h)
    VRFW.host.menu_command(HL_CMND_SCALE, HL_SKILL_OPEN, s, s, 1, 0)
    local cx = HL_SO_BASE_X + x + w * (HL_PLATE_VX0 + HL_PLATE_VX1) / 2
    local cy = HL_SO_BASE_Y
    VRFW.host.menu_command(HL_CMND_POS, HL_SKILL_OPEN, cx + BetterUI.hud_layout.SKILL_OPEN_DX - s * cx, cy + BetterUI.hud_layout.SKILL_OPEN_DY - s * cy, 0, 0)
  elseif layer == HL_CANCEL_GUIDE then
    local s = BetterUI.hud_layout.ACTION_PLATE_SCALE
    VRFW.host.menu_command(HL_CMND_SCALE, HL_CANCEL_GUIDE, s, s, 1, 0)
  elseif layer == HL_RING then
    if not BetterUI.hud_layout.TACTICS_LEFT then
      return
    end
    local x = -BetterUI.hud_layout.SCREEN_W + BetterUI.hud_layout.TACTICS_RING_X
    local dy = BetterUI.hud_layout.TACTICS_RING_Y - HL_RING_Y
    if BetterUI.hud_layout.TACTICS_FLIP then
      VRFW.host.menu_command(HL_CMND_SCALE, HL_RING, -1, 1, 1, 0)
      VRFW.host.menu_command(HL_CMND_POS, HL_RING, x + HL_RING_X, dy, 0, 0)
    else
      VRFW.host.menu_command(HL_CMND_POS, HL_RING, x - HL_RING_X, dy, 0, 0)
    end
  elseif layer == HL_BASE or layer == HL_COACH then
    VRFW.host.menu_command(HL_CMND_POS, layer, hl_menu_dx, 0, 0, 0)
  elseif layer == HL_TAC_PLATE then
    local s = BetterUI.hud_layout.TACTICS_PLATE_SCALE
    local pull = (1 - s) * HL_TAC_HALF_W
    for i = 0, 3 do
      local dx = (i == 1 and pull) or (i == 3 and -pull) or 0
      VRFW.host.menu_command(HL_CMND_SCALE, HL_TAC_PLATE, s, s, 1, i)
      VRFW.host.menu_command(HL_CMND_POS, HL_TAC_PLATE, dx, 0, 0, i)
    end
  end
end

-- Places the action plates; any other action uses 1.
local function HL_PlaceActionPlates()
  for i = 0, HL_BASE_CMD_COUNT - 1 do
    if hl_plate_ready[i] then
      local s = HL_SMALL_PLATE_ACTIONS[hl_plate_action[i]] and BetterUI.hud_layout.ACTION_PLATE_SCALE or 1
      if hl_plate_scale_sent[i] ~= s then
        VRFW.host.menu_command(HL_CMND_SCALE, HL_BASE_CMD, s, s, 1, i)
        hl_plate_scale_sent[i] = s
      end
    end
  end
end

